use crate::client::{print, Client};
use anyhow::bail;
use den_core::Message;
use std::collections::BTreeMap;

pub(crate) struct Args {
    pub channel: String,
    pub before: Option<String>,
    pub after: Option<String>,
    pub limit: u32,
    pub all: bool,
}

/// Reject impossible queries before any HTTP request, one page or all.
pub(crate) fn validate(before: Option<&str>, after: Option<&str>, limit: u32) -> anyhow::Result<()> {
    anyhow::ensure!(
        before.is_none() || after.is_none(),
        "Use --before or --after, not both"
    );
    anyhow::ensure!((1..=200).contains(&limit), "Limit must be 1-200");
    Ok(())
}

pub(crate) fn run(c: &Client, a: Args) -> anyhow::Result<()> {
    validate(a.before.as_deref(), a.after.as_deref(), a.limit)?;
    if let Some(v) = &a.before {
        crate::id(v)?;
    }
    if let Some(v) = &a.after {
        crate::id(v)?;
    }
    let channel = c.resolve_channel(&a.channel)?;
    let fetch = |before: Option<&str>, after: Option<&str>| -> anyhow::Result<Vec<Message>> {
        let mut path = format!("/channels/{channel}/messages?limit={}", a.limit);
        if let Some(v) = before {
            path.push_str(&format!("&before={v}"));
        }
        if let Some(v) = after {
            path.push_str(&format!("&after={v}"));
        }
        c.get(&path)
    };
    if !a.all {
        return print(&fetch(a.before.as_deref(), a.after.as_deref())?);
    }
    print(&all_pages(a.before, a.after, a.limit, fetch)?)
}

/// Walk every page matching the bounds and merge them into one array, ordered
/// by ascending message ID without duplicates. `fetch` performs one page
/// request; pages arrive ascending, `before`/no cursor starts from the newest
/// page and walks backwards, `after` starts from the oldest and walks forwards.
fn all_pages<F>(
    before: Option<String>,
    after: Option<String>,
    limit: u32,
    mut fetch: F,
) -> anyhow::Result<Vec<Message>>
where
    F: FnMut(Option<&str>, Option<&str>) -> anyhow::Result<Vec<Message>>,
{
    let forwards = after.is_some();
    // Exclusive bound of the next page request.
    let mut bound = after.or(before);
    let mut merged: BTreeMap<String, Message> = BTreeMap::new();
    loop {
        let page = fetch(
            if forwards { None } else { bound.as_deref() },
            if forwards { bound.as_deref() } else { None },
        )?;
        if page.is_empty() || page.len() < limit as usize {
            return Ok(merged.into_values().collect());
        }
        let fresh = page.iter().any(|m| !merged.contains_key(&m.id));
        for m in page {
            merged.insert(m.id.clone(), m);
        }
        // Pages are ascending: the walk edge is the oldest message going
        // backwards, the newest going forwards.
        let edge = if forwards {
            page.last().expect("checked nonempty").id.clone()
        } else {
            page.first().expect("checked nonempty").id.clone()
        };
        let progressed = match &bound {
            Some(previous) if forwards => edge > *previous,
            Some(previous) => edge < *previous,
            None => true,
        };
        if !fresh || !progressed {
            bail!("Pagination stopped making progress at message {edge}");
        }
        bound = Some(edge);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn msg(id: &str) -> Message {
        Message {
            id: id.into(),
            channel_id: "01CHANNEL".into(),
            author_id: "01AUTHOR".into(),
            content: format!("m{id}"),
            reply_to: None,
            created_at: String::new(),
            edited_at: None,
            attachments: Vec::new(),
            objects: Vec::new(),
            reactions: Vec::new(),
            mention_ids: Vec::new(),
        }
    }

    fn ids(messages: &[Message]) -> Vec<&str> {
        messages.iter().map(|m| m.id.as_str()).collect()
    }

    #[test]
    fn validate_rejects_conflicting_bounds_and_bad_limits() {
        assert!(validate(None, None, 50).is_ok());
        assert!(validate(Some("01A"), None, 1).is_ok());
        assert!(validate(None, Some("01A"), 200).is_ok());
        assert!(validate(Some("01A"), Some("01B"), 50).is_err());
        assert!(validate(None, None, 0).is_err());
        assert!(validate(None, None, 201).is_err());
    }

    #[test]
    fn all_walks_backwards_from_newest_without_a_cursor() {
        // Server semantics: newest page first, ascending rows, exclusive before.
        let all: Vec<Message> = (1..=7).map(|i| msg(&format!("m{i}"))).collect();
        let mut cursors = Vec::new();
        let out = all_pages(None, None, 3, |before, _| {
            cursors.push(before.map(str::to_string));
            let mut page: Vec<Message> = all
                .iter()
                .filter(|m| before.is_none_or(|b| m.id < b))
                .cloned()
                .collect();
            let start = page.len().saturating_sub(3);
            page.drain(..start);
            Ok(page)
        })
        .unwrap();
        assert_eq!(ids(&out), ["m1", "m2", "m3", "m4", "m5", "m6", "m7"]);
        assert_eq!(cursors, [None, Some("m5"), Some("m2")]);
    }

    #[test]
    fn all_with_before_walks_backwards_from_the_bound() {
        let all: Vec<Message> = (1..=7).map(|i| msg(&format!("m{i}"))).collect();
        let mut cursors = Vec::new();
        let out = all_pages(Some("m6".into()), None, 3, |before, _| {
            cursors.push(before.map(str::to_string));
            let mut page: Vec<Message> = all
                .iter()
                .filter(|m| before.is_none_or(|b| m.id < b))
                .cloned()
                .collect();
            let start = page.len().saturating_sub(3);
            page.drain(..start);
            Ok(page)
        })
        .unwrap();
        assert_eq!(ids(&out), ["m1", "m2", "m3", "m4", "m5"]);
        assert_eq!(cursors, [Some("m6"), Some("m3"), Some("m1")]);
    }

    #[test]
    fn all_with_after_walks_forwards_from_the_bound() {
        let all: Vec<Message> = (1..=7).map(|i| msg(&format!("m{i}"))).collect();
        let mut cursors = Vec::new();
        let out = all_pages(None, Some("m2".into()), 3, |_, after| {
            cursors.push(after.map(str::to_string));
            Ok(all
                .iter()
                .filter(|m| m.id > after.unwrap())
                .take(3)
                .cloned()
                .collect())
        })
        .unwrap();
        assert_eq!(ids(&out), ["m3", "m4", "m5", "m6", "m7"]);
        assert_eq!(cursors, [Some("m2"), Some("m5")]);
    }

    #[test]
    fn all_fails_promptly_when_a_full_page_repeats() {
        // A broken server that ignores the cursor and always returns the newest
        // full page must not hang the walk.
        let newest: Vec<Message> = (5..=7).map(|i| msg(&format!("m{i}"))).collect();
        let result = all_pages(None, None, 3, |_, _| Ok(newest.clone()));
        assert!(result.is_err());
    }

    #[test]
    fn all_fails_promptly_when_the_cursor_never_moves() {
        // Full pages whose walk edge stays put: no progress, fail instead of loop.
        let stuck: Vec<Message> = (4..=6).map(|i| msg(&format!("m{i}"))).collect();
        let result = all_pages(Some("m9".into()), None, 3, |before, _| {
            let page: Vec<Message> = stuck
                .iter()
                .filter(|m| before.is_none_or(|b| m.id < b))
                .cloned()
                .collect();
            Ok(if page.len() == 3 { page } else { stuck.clone() })
        });
        assert!(result.is_err());
    }

    #[test]
    fn all_surfaces_later_page_errors_without_partial_output() {
        let result = all_pages(None, None, 3, |before, _| {
            if before.is_some() {
                return Err(anyhow::anyhow!("500: internal"));
            }
            Ok((5..=7).map(|i| msg(&format!("m{i}"))).collect())
        });
        assert!(result.is_err());
        // The error type carries no partial array to print.
        let message = result.unwrap_err().to_string();
        assert_eq!(message, "500: internal");
    }
}

